import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type * as React from 'react'
import {memo, useCallback, useContext} from 'react'

import {
  PipelinesTarget,
  PipelinesTargetContext,
} from '../../../../pages/PipelinesPages/contexts/targetContext'
import type {LogView} from '../../BuildLog.types'
import {Status} from '../../BuildLog.types'
import {getTextWithSpaceIndents, leftPad} from '../BuildLogMessages.utils'

import LinkedMessage from './LinkedMessage/LinkedMessage'
import LogMessageDuration from './LogMessageDuration/LogMessageDuration'
import LogMessageSearchHighlighting from './LogMessageSearchHighlighting/LogMessageSearchHighlighting'
import LogMessageText from './LogMessageText/LogMessageText'
import StepStatus from './StepStatus/StepStatus'

import styles from './LogMessage.module.css'

type Props = {
  className?: string | null | undefined
  treeView?: boolean
  id: number
  level: number
  expandable?: boolean | null | undefined
  expanded?: boolean | null | undefined
  text: string
  duration?: number | null | undefined
  status: Status
  blockType: string | null | undefined
  childrenEmpty?: boolean
  childrenLoading?: boolean
  breakLines?: boolean
  parseLinks?: boolean | null | undefined
  parseAnsi?: boolean | null | undefined
  linkedMessageId?: number | null | undefined
  verbose?: boolean | null | undefined
  onMessageToggle?: (
    index: number,
    expand: boolean,
    withFocus?: boolean,
    childrenEmpty?: boolean | null,
  ) => unknown
  role?: string
  onLinkedMessageClick?: (event: React.MouseEvent<any>, id: number) => unknown
  searchQuery?: string | null | undefined
  searchMatchPosition?: number | null
  scrollToSearch?: boolean | null
  showDuration: boolean
  timestamp?: string
  logView?: LogView
  running?: boolean | undefined
}

function LogMessage({
  className,
  treeView,
  id,
  level,
  expandable,
  expanded,
  text,
  duration,
  status,
  blockType,
  childrenEmpty,
  childrenLoading,
  breakLines,
  parseLinks,
  parseAnsi,
  linkedMessageId,
  verbose,
  onMessageToggle,
  role,
  onLinkedMessageClick,
  searchQuery,
  searchMatchPosition,
  scrollToSearch,
  showDuration,
  timestamp,
  logView,
  running,
}: Props) {
  const pipelinesTarget = useContext(PipelinesTargetContext)

  const isPipelines =
    pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP ||
    pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR ||
    pipelinesTarget === PipelinesTarget.JOB_DEBUG_POPUP ||
    pipelinesTarget === PipelinesTarget.JOB_DEBUG_PANEL

  const isLargeStepHeading = isPipelines && blockType === 'teamcity-build-step-type'

  const onChevronClick = useCallback(
    (event: React.MouseEvent<any> | null | undefined) => {
      if (event) {
        event.preventDefault()
        event.stopPropagation()
      }

      onMessageToggle?.(id, !expanded, false, childrenEmpty)
    },
    [childrenEmpty, expanded, id, onMessageToggle],
  )

  const getExpandCollapseIcon = useCallback(() => {
    let expandIcon = 'expand-12px'
    let collapseIcon = 'collapse-12px'

    if (isLargeStepHeading) {
      expandIcon = 'chevron-right'
      collapseIcon = 'chevron-down'
    }

    return expanded === true ? collapseIcon : expandIcon
  }, [expanded, isLargeStepHeading])

  const spaces = leftPad(level)
  const textWithSpaceIndents = getTextWithSpaceIndents(text, spaces)

  return (
    <div
      className={classNames(styles.message, className, {
        [styles.largeStepHeading]: isLargeStepHeading,
        [styles.error]: status === Status.ERROR || status === Status.TRACE_ERROR,
        [styles.warning]: status === Status.WARNING,
        [styles.verbose]: verbose,
        [styles.breakLines]: breakLines,
        [styles.treeMessage]: treeView,
      })}
      role={role}
      data-log-message
      data-test-log-message
    >
      {isLargeStepHeading && <StepStatus status={status} duration={duration} running={running} />}
      <div className={styles.text}>
        <LogMessageText text={textWithSpaceIndents} parseLinks={parseLinks} parseAnsi={parseAnsi} />
        {searchQuery != null && (
          <LogMessageSearchHighlighting
            text={textWithSpaceIndents}
            searchQuery={searchQuery}
            className={styles.searchHighlighiting}
            searchMatchPosition={searchMatchPosition}
            scrollToSearch={scrollToSearch}
          />
        )}
        {linkedMessageId != null && onLinkedMessageClick != null && (
          <>
            {' '}
            <LinkedMessage
              linkedMessageId={linkedMessageId}
              onClick={onLinkedMessageClick}
              logView={logView}
            />
          </>
        )}
        {showDuration && (
          <LogMessageDuration
            duration={duration}
            className={styles.duration}
            timestamp={timestamp}
            running={running}
          />
        )}
      </div>
      {treeView === true && expandable === true && childrenLoading !== true && (
        <IconButton
          title={expanded === true ? 'Collapse' : 'Expand'}
          className={styles.collapseButton}
          iconClassName={styles.collapseIcon}
          icon={getExpandCollapseIcon()}
          childrenLeft
          onClick={onChevronClick}
          data-test-log-message-toggle
        >
          {spaces}
        </IconButton>
      )}
      {childrenLoading === true && (
        <span className={styles.loaderWrapper}>
          {spaces}
          <LoaderInline className={styles.loader} />
        </span>
      )}
    </div>
  )
}

export default memo(LogMessage)
