import {utc} from 'moment'

import type {SelectionState} from '../../../../hooks/useGridSelection'
import {parseDateToObj} from '../../../../utils/dateTimeUtils'
import {PipelinesTarget} from '../../../pages/PipelinesPages/contexts/targetContext'
import type {BuildLogMessage} from '../BuildLog.types'
import {FullLogTarget} from '../BuildLog.types'
import {ansiRegexpString} from '../BuildLog.utils'

import styles from './BuildLogMessages.module.css'

export const ROW_HEIGHT = 18
const UNIT = 8
const VERTICAL_ROW_PADDING = UNIT * 2
const TARGET_POPUP_ROW_PADDING = 98
const TARGET_PAGE_ROW_PADDING = TARGET_POPUP_ROW_PADDING + 2 * UNIT
const TARGET_PIPELINE_POPUP_ROW_PADDING = TARGET_POPUP_ROW_PADDING + UNIT / 2
const TARGET_PIPELINE_SIDEBAR_ROW_PADDING = TARGET_POPUP_ROW_PADDING + UNIT / 2
const DEFAULT_UNCALCULATED_CHAR_WIDTH = 7.25
let cachedCharWidth: number | null | undefined = null

const getCharWidth = (className: string): number => {
  if (cachedCharWidth != null) {
    return cachedCharWidth
  }

  const testString = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/-.= ()"'
  const span = document.createElement('span')
  span.innerHTML = testString
  const div = document.createElement('div')
  div.className += className
  div.style.visibility = 'none'
  div.style.opacity = '0'
  div.style.position = 'absolute'
  div.style.left = '-1000px'
  div.style.top = '-1000px'
  div.appendChild(span)

  if (document.body != null) {
    document.body.appendChild(div)
  }

  const round = 100
  let result = Math.ceil((span.getBoundingClientRect().width / testString.length) * round) / round

  if (result === 0) {
    result = DEFAULT_UNCALCULATED_CHAR_WIDTH
  }

  if (document.body != null) {
    document.body.removeChild(div)
  }

  cachedCharWidth = result
  return result
}

const getRowPadding = (
  target: FullLogTarget,
  pipelinesTarget?: PipelinesTarget | null | undefined,
): number => {
  if (
    pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR ||
    pipelinesTarget === PipelinesTarget.JOB_DEBUG_PANEL
  ) {
    return TARGET_PIPELINE_SIDEBAR_ROW_PADDING
  }
  if (
    pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP ||
    pipelinesTarget === PipelinesTarget.JOB_DEBUG_POPUP
  ) {
    return TARGET_PIPELINE_POPUP_ROW_PADDING
  }
  if (target === FullLogTarget.PAGE) {
    return TARGET_PAGE_ROW_PADDING
  }
  return TARGET_POPUP_ROW_PADDING
}

export const calculateMessageHeight = (
  message: BuildLogMessage | null | undefined,
  listWidth: number | null | undefined,
  last: boolean,
  softWrapLines: boolean,
  running: boolean,
  target: FullLogTarget,
  pipelinesTarget?: PipelinesTarget | null | undefined,
): number => {
  const lastPadding = running && last ? 2 * ROW_HEIGHT : 0

  if (message?.linesLengths == null) {
    return ROW_HEIGHT + lastPadding
  }

  let linesCount = message.linesLengths.length

  if (softWrapLines && listWidth != null && listWidth > 0) {
    const charWidth = getCharWidth(styles.messages)

    const padding = getRowPadding(target, pipelinesTarget)
    const charsPerLineCount = Math.floor((listWidth - padding) / charWidth)

    if (message.linesLengths != null) {
      linesCount = message.linesLengths.reduce(
        (acc: number, lineLength: number) =>
          acc + (lineLength > 0 ? Math.ceil(lineLength / charsPerLineCount) : 1),
        0,
      )
    }
  }

  const isPipelineContext =
    pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP ||
    pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR ||
    pipelinesTarget === PipelinesTarget.JOB_DEBUG_POPUP ||
    pipelinesTarget === PipelinesTarget.JOB_DEBUG_PANEL

  if (isPipelineContext && message.blockType === 'teamcity-build-step-type') {
    return linesCount * ROW_HEIGHT + VERTICAL_ROW_PADDING + lastPadding
  }

  return linesCount * ROW_HEIGHT + lastPadding
}
export const calculateTotalMessagesHeight = (
  messages: ReadonlyArray<BuildLogMessage | null | undefined>,
  listWidth: number,
  softWrapLines: boolean,
  running: boolean,
  target: FullLogTarget,
  pipelinesTarget?: PipelinesTarget | null | undefined,
): number =>
  messages.reduce(
    (acc: number, message: BuildLogMessage | null | undefined, index: number) =>
      acc +
      calculateMessageHeight(
        message,
        listWidth,
        index === messages.length - 1,
        softWrapLines,
        running,
        target,
        pipelinesTarget,
      ),
    0,
  )
export const getMessageWidth = (
  length: number,
  target: FullLogTarget,
  pipelinesTarget?: PipelinesTarget | null | undefined,
): number => {
  const width = length * getCharWidth(styles.messages) + 2 * UNIT
  const padding = getRowPadding(target, pipelinesTarget)
  return width + padding
}

export const leftPad = (level: number): string => Array(level).join('\u00a0\u00a0')

export const getTextWithSpaceIndents = (text: string, spaces: string): string =>
  text
    .split('\n')
    .map(line => `${spaces}${line}`)
    .join('\n')

export const printMessageTime = (timestamp: string | undefined, isAutodetectTimeZone: boolean) =>
  timestamp != null
    ? `${parseDateToObj(timestamp, isAutodetectTimeZone).format('HH:mm:ss')}\u00a0`
    : ''

export const printRelativeTime = (
  timestamp: string | undefined,
  buildStart: string | null | undefined,
  isAutodetectTimeZone: boolean,
) => {
  if (!timestamp || !buildStart) {
    return '00:00:00'
  }
  const currentDate = parseDateToObj(timestamp, isAutodetectTimeZone)
  const buildStartDate = parseDateToObj(buildStart, isAutodetectTimeZone)
  const diff = currentDate.diff(buildStartDate)
  return `${utc(diff < 0 ? 0 : diff).format('HH:mm:ss')}\u00a0`
}

function getMessageTextForCoping(message: BuildLogMessage): string {
  const text = getTextWithSpaceIndents(message.text, leftPad(message.level)).replace(/\u00a0/g, ' ')
  return message.containAnsi ? text.replace(new RegExp(ansiRegexpString, 'ig'), '') : text
}

export const getTextForCoping = ({
  selectionState,
  messages,
  isAutodetectTimeZone,
}: {
  selectionState: SelectionState
  messages: ReadonlyArray<BuildLogMessage | null | undefined>
  isAutodetectTimeZone: boolean
}): string => {
  if (selectionState == null || messages.length === 0) {
    return ''
  }

  let startId: number
  let absoluteStartOffset: number
  let endId: number
  let absoluteEndOffset: number

  const isSingleRowSelection =
    selectionState.focusRowId === selectionState.anchorRowId &&
    selectionState.anchorOffset < selectionState.focusOffset
  const isAnchorHigher = selectionState.anchorRowId < selectionState.focusRowId

  if (isSingleRowSelection || isAnchorHigher) {
    startId = selectionState.anchorRowId
    absoluteStartOffset = selectionState.anchorAbsoluteOffset
    endId = selectionState.focusRowId
    absoluteEndOffset = selectionState.focusAbsoluteOffset
  } else {
    startId = selectionState.focusRowId
    absoluteStartOffset = selectionState.focusAbsoluteOffset
    endId = selectionState.anchorRowId
    absoluteEndOffset = selectionState.anchorAbsoluteOffset
  }

  const copyMessages: Array<string> = []
  let i = 0
  let message: BuildLogMessage | null | undefined
  let insideSelection = false

  do {
    message = messages[i]
    i++
    if (message != null) {
      const text = getMessageTextForCoping(message)
      const time = printMessageTime(message.timestamp, isAutodetectTimeZone)
      const row = `${time}${text}`

      if (message.id === startId && message.id === endId) {
        copyMessages.push(row.slice(absoluteStartOffset, absoluteEndOffset))
        insideSelection = false
      } else if (message.id === startId) {
        copyMessages.push(absoluteStartOffset > 0 ? row.slice(absoluteStartOffset) : row)
        insideSelection = true
      } else if (message.id > startId && message.id < endId) {
        copyMessages.push(row)
      } else if (message.id === endId) {
        copyMessages.push(row.slice(0, absoluteEndOffset))
        insideSelection = false
      }
    } else if (insideSelection) {
      copyMessages.push('\n~~~~~~~~~~~~~~~~~~~~~\n\n')
    }
  } while (message == null || message.id < endId)

  return copyMessages.join('\n')
}
