import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import classNames from 'classnames'
import * as React from 'react'

import Icon from '../../../common/Icon/Icon'
import {
  PipelinesTargetContext,
  PipelinesTarget,
} from '../../../pages/PipelinesPages/contexts/targetContext'
import {FullLogTarget} from '../BuildLog.types'

import styles from './BuildLogInfo.module.css'

type Props = {
  type: 'loading' | 'empty' | 'disabled' | 'no-stacktrace'
  className?: string
  target?: FullLogTarget
}

function BuildLogInfo({type, className, target}: Props) {
  const pipelinesTarget = React.useContext(PipelinesTargetContext)

  const classes = classNames(className, styles.info, {
    [styles.pageTarget]: target === FullLogTarget.PAGE,
    [styles.jobDetailsPopupTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP,
    [styles.jobDetailsSidebarTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR,
    [styles.jobDebugPanelTarget]: pipelinesTarget === PipelinesTarget.JOB_DEBUG_PANEL,
    [styles.jobDebugPopupTarget]: pipelinesTarget === PipelinesTarget.JOB_DEBUG_POPUP,
  })

  return (
    <div className={classes} data-test-build-log-info>
      {type === 'loading' && <LoaderInline>{'Build log is loading...'}</LoaderInline>}
      {(type === 'empty' || type === 'disabled' || type === 'no-stacktrace') && (
        <Icon name="warning" className={styles.infoIcon} />
      )}
      {type === 'empty' && 'Build log is empty'}
      {type === 'no-stacktrace' && 'No stacktrace'}
      {type === 'disabled' && 'Build log functionality is disabled on server'}
    </div>
  )
}

export default BuildLogInfo
