import classNames from 'classnames'

import Icon from '../../../../../common/Icon/Icon'
import {Status} from '../../../BuildLog.types'

import styles from './StepStatus.module.css'

type Props = {
  status: Status
  duration: number | null | undefined
  running: boolean | undefined
}

function StepStatus({status, duration, running}: Props) {
  const isRunning = running && duration == null
  const isError = status === Status.ERROR || status === Status.TRACE_ERROR
  const isWarning = status === Status.WARNING

  let icon = 'success'

  if (isError) {
    icon = 'exception'
  }
  if (isWarning) {
    icon = 'warning'
  }
  if (isRunning) {
    icon = 'running'
  }

  return (
    <Icon
      className={classNames(styles.icon, {
        [styles.error]: isError,
        [styles.warning]: isWarning,
        [styles.running]: isRunning,
      })}
      name={icon}
    />
  )
}

export default StepStatus
